CREATE TYPE "Role" AS ENUM ('STUDENT', 'ADMIN');
CREATE TYPE "OpportunityStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'EXPIRED', 'ARCHIVED');
CREATE TYPE "VerificationStatus" AS ENUM ('UNCHECKED', 'IN_REVIEW', 'VERIFIED', 'NEEDS_ATTENTION');
CREATE TYPE "SourceCredibility" AS ENUM ('UNKNOWN', 'COMMUNITY', 'OFFICIAL');
CREATE TYPE "ApplicationStatus" AS ENUM ('INTERESTED', 'PREPARING', 'APPLIED', 'INTERVIEWING', 'OFFER', 'NOT_PROCEEDING');
CREATE TYPE "DeliveryFormat" AS ENUM ('REMOTE', 'HYBRID', 'IN_PERSON');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'STUDENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StudentProfile" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"studyLevel" TEXT,"fieldOfStudy" TEXT,"country" TEXT,"nationality" TEXT,"academicRequirements" JSONB,"preferredCategories" TEXT[] DEFAULT ARRAY[]::TEXT[],"preferredLocations" TEXT[] DEFAULT ARRAY[]::TEXT[],"preferredFormats" TEXT[] DEFAULT ARRAY[]::TEXT[],"interests" TEXT[] DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "StudentProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Opportunity" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"provider" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"eligibleCountries" TEXT[] DEFAULT ARRAY[]::TEXT[],"locations" TEXT[] DEFAULT ARRAY[]::TEXT[],"studyLevels" TEXT[] DEFAULT ARRAY[]::TEXT[],"fields" TEXT[] DEFAULT ARRAY[]::TEXT[],"eligibility" JSONB,"requiredDocuments" TEXT[] DEFAULT ARRAY[]::TEXT[],"fundingAmount" DECIMAL(14,2),"fundingCurrency" TEXT,"fundingType" TEXT,"format" "DeliveryFormat","applicationUrl" TEXT NOT NULL,"publishedAt" TIMESTAMP(3),"deadline" TIMESTAMP(3),"deadlineTimezone" TEXT,"status" "OpportunityStatus" NOT NULL DEFAULT 'DRAFT',"sourceCredibility" "SourceCredibility" NOT NULL DEFAULT 'UNKNOWN',"verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'UNCHECKED',"lastSourceCheckAt" TIMESTAMP(3),"demo" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Opportunity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpportunitySource" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"url" TEXT NOT NULL,"name" TEXT,"retrievedAt" TIMESTAMP(3),"lastAttemptAt" TIMESTAMP(3),"lastSuccessAt" TIMESTAMP(3),"failureReason" TEXT,"authorized" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OpportunitySource_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavedOpportunity" ("userId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SavedOpportunity_pkey" PRIMARY KEY ("userId","opportunityId"));
CREATE TABLE "Application" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"status" "ApplicationStatus" NOT NULL DEFAULT 'INTERESTED',"notes" TEXT,"appliedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Application_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VerificationEvent" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"actorUserId" TEXT,"action" TEXT NOT NULL,"details" JSONB,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VerificationEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("userId" TEXT NOT NULL,"deadlineReminders" BOOLEAN NOT NULL DEFAULT true,"recommendationUpdates" BOOLEAN NOT NULL DEFAULT true,"emailEnabled" BOOLEAN NOT NULL DEFAULT false,"timezone" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("userId"));
CREATE TABLE "Session" ("sid" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Session_pkey" PRIMARY KEY ("sid"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_role_idx" ON "User"("role");
CREATE UNIQUE INDEX "StudentProfile_userId_key" ON "StudentProfile"("userId"); CREATE UNIQUE INDEX "Opportunity_slug_key" ON "Opportunity"("slug");
CREATE INDEX "Opportunity_status_deadline_idx" ON "Opportunity"("status","deadline"); CREATE INDEX "Opportunity_category_status_idx" ON "Opportunity"("category","status"); CREATE INDEX "Opportunity_verificationStatus_idx" ON "Opportunity"("verificationStatus"); CREATE INDEX "Opportunity_provider_idx" ON "Opportunity"("provider");
CREATE UNIQUE INDEX "OpportunitySource_opportunityId_url_key" ON "OpportunitySource"("opportunityId","url"); CREATE INDEX "OpportunitySource_retrievedAt_idx" ON "OpportunitySource"("retrievedAt");
CREATE INDEX "SavedOpportunity_opportunityId_idx" ON "SavedOpportunity"("opportunityId"); CREATE UNIQUE INDEX "Application_userId_opportunityId_key" ON "Application"("userId","opportunityId"); CREATE INDEX "Application_userId_status_idx" ON "Application"("userId","status"); CREATE INDEX "VerificationEvent_opportunityId_checkedAt_idx" ON "VerificationEvent"("opportunityId","checkedAt"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt"); CREATE INDEX "Session_userId_idx" ON "Session"("userId");
ALTER TABLE "StudentProfile" ADD CONSTRAINT "StudentProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OpportunitySource" ADD CONSTRAINT "OpportunitySource_opportunityId_fkey" FOREIGN KEY ("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SavedOpportunity" ADD CONSTRAINT "SavedOpportunity_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SavedOpportunity" ADD CONSTRAINT "SavedOpportunity_opportunityId_fkey" FOREIGN KEY ("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Application" ADD CONSTRAINT "Application_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Application" ADD CONSTRAINT "Application_opportunityId_fkey" FOREIGN KEY ("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "VerificationEvent" ADD CONSTRAINT "VerificationEvent_opportunityId_fkey" FOREIGN KEY ("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "NotificationPreference" ADD CONSTRAINT "NotificationPreference_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
